func (a *fyneApp) Run() {
	a.runMutex.Lock()

	if a.running {
		a.runMutex.Unlock()
		return
	}

	a.running = true
	a.runMutex.Unlock()

	a.driver.Run()
}

func (a *fyneApp) Quit() {
	for _, window := range a.driver.AllWindows() {
		window.Close()
	}

	a.driver.Quit()
	a.settings.stopWatching()
	a.running = false
}

