import (
	"fmt"
	"sync"
)

// StringFormat supports binding a formatted string from a variable number of input DataItem bindings.
//
// Since: 2.5
type StringFormat interface {
	String
	AddListener(DataListener)
	RemoveListener(DataListener)
}

// NewSprintf returns a new StringFormat binding that formats its output using the specified format string and data bindings.
// The format string follows the same rules as fmt.Sprintf. The binding listens to all input sources and updates when any changes.
//
// Since: 2.5
func NewSprintf(format string, bindings ...DataItem) StringFormat {
	s := &boundSprintf{
		format:   format,
		bindings: bindings,
	}

	// Listen to all input bindings
	listener := NewDataListener(func() {
		s.lock.Lock()
		defer s.lock.Unlock()
		s.trigger()
	})

	for _, b := range bindings {
		b.AddListener(listener)
	}

	return s
}

type boundSprintf struct {
	base

	format   string
	bindings []DataItem
	lock     sync.RWMutex
}

func (s *boundSprintf) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()

	// Gather all values from bound items
	values := make([]interface{}, len(s.bindings))
	for i, b := range s.bindings {
		switch typed := b.(type) {
		case String:
			val, err := typed.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		case Int:
			val, err := typed.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		case Float:
			val, err := typed.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		case Bool:
			val, err := typed.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		case Untyped:
			val, err := typed.Get()
			if err != nil {
				return "", err
			}
			values[i] = val
		default:
			values[i] = nil
		}
	}

	return fmt.Sprintf(s.format, values...), nil
}

func (s *boundSprintf) Set(string) error {
	// StringFormat bindings are read-only
	return fmt.Errorf("cannot set formatted string binding")
}
