// Validatable is an interface for specifying if a widget is validatable.
//
// Since: 1.4
type Validatable interface {
	Validate() error

	// SetOnValidationChanged is used to set the callback that will be triggered when the validation state changes.
	// The function might be overwritten by a parent that cares about child validation (e.g. widget.Form).
	SetOnValidationChanged(func(error))
}

// StringValidator is a function signature for validating string inputs.
//
// Since: 1.4
type StringValidator func(string) error

// NewAllValidator returns a new validator that requires all of the provided validators to pass.
// If any validator returns an error, that error is returned immediately.
//
// Since: 2.5
func NewAllValidator(validators ...StringValidator) StringValidator {
	return func(s string) error {
		for _, validator := range validators {
			if err := validator(s); err != nil {
				return err
			}
		}
		return nil
	}
}
